// Filtra carritos que valen la pena: con mail, con plata, y con mas de 2 horas.
// Se saltea los que ya se avisaron antes (memoria en workflow static data).
const staticData = $getWorkflowStaticData('global');
staticData.avisados = staticData.avisados || [];

const ahora = Date.now();
const DOS_HORAS = 2 * 60 * 60 * 1000;
const SIETE_DIAS = 7 * 24 * 60 * 60 * 1000;

const carritos = $input.first().json.checkouts || [];
const salida = [];

for (const c of carritos) {
  if (!c.email) continue;                                  // sin mail no se puede contactar
  const total = parseFloat(c.total_price || 0);
  if (total <= 0) continue;
  const creado = new Date(c.created_at).getTime();
  const edad = ahora - creado;
  if (edad < DOS_HORAS) continue;                           // dejarlo respirar
  if (edad > SIETE_DIAS) continue;                          // ya esta frio
  if (staticData.avisados.includes(String(c.id))) continue; // ya avisado

  const items = (c.line_items || [])
    .map(li => `${li.quantity}x ${li.title}`).join(', ');
  const nombre = (c.customer && c.customer.first_name) || '';
  const horas = Math.round(edad / 3600000);

  salida.push({ json: {
    id: String(c.id),
    email: c.email,
    nombre,
    total,
    items,
    horas,
    link: c.abandoned_checkout_url || ''
  }});

  staticData.avisados.push(String(c.id));
}

// no dejar crecer la memoria para siempre
if (staticData.avisados.length > 300) {
  staticData.avisados = staticData.avisados.slice(-300);
}

return salida;
